CREATE TYPE public.app_role AS ENUM ('donor','organizer','admin');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', approval_status text NOT NULL DEFAULT 'approved' CHECK (approval_status IN ('pending','approved','rejected')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'donor');
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(uid uuid, requested public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=uid AND role=requested) $$;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE selected_role public.app_role; BEGIN selected_role := CASE WHEN NEW.raw_user_meta_data->>'account_type'='organizer' THEN 'organizer'::public.app_role ELSE 'donor'::public.app_role END; INSERT INTO public.profiles(id,full_name,approval_status) VALUES(NEW.id,COALESCE(NEW.raw_user_meta_data->>'full_name',NEW.raw_user_meta_data->>'name','Member'),CASE WHEN selected_role='organizer' THEN 'pending' ELSE 'approved' END); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,selected_role); RETURN NEW; END $$;
CREATE TRIGGER launchly_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organizer_id uuid REFERENCES public.profiles(id), organizer_name text NOT NULL DEFAULT '', title text NOT NULL CHECK(length(title) BETWEEN 5 AND 150), description text NOT NULL CHECK(length(description)>=20), category text NOT NULL CHECK(category IN ('Education','Healthcare','Environment','Hunger Relief','Animal Welfare','Community Development')), goal_amount numeric NOT NULL CHECK(goal_amount>0 AND goal_amount<=100000000), image_url text, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('draft','pending','approved','rejected')), is_sample boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.campaigns TO anon,authenticated; GRANT INSERT,UPDATE ON public.campaigns TO authenticated; GRANT ALL ON public.campaigns TO service_role; ALTER TABLE public.campaigns ENABLE ROW LEVEL SECURITY;
CREATE POLICY campaigns_read ON public.campaigns FOR SELECT USING (status='approved' OR organizer_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY campaigns_create ON public.campaigns FOR INSERT TO authenticated WITH CHECK(organizer_id=auth.uid() AND public.has_role(auth.uid(),'organizer') AND EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND approval_status='approved') AND status IN ('draft','pending') AND NOT is_sample);
CREATE POLICY campaigns_edit ON public.campaigns FOR UPDATE TO authenticated USING(organizer_id=auth.uid() AND status IN ('draft','pending','rejected')) WITH CHECK(organizer_id=auth.uid() AND status IN ('draft','pending') AND NOT is_sample);
CREATE FUNCTION public.validate_campaign_edit() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.organizer_id IS DISTINCT FROM OLD.organizer_id OR NEW.is_sample IS DISTINCT FROM OLD.is_sample THEN RAISE EXCEPTION 'Campaign ownership cannot be changed'; END IF; IF NOT public.has_role(auth.uid(),'admin') AND (NOT public.has_role(auth.uid(),'organizer') OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND approval_status='approved')) THEN RAISE EXCEPTION 'An approved organizer account is required'; END IF; NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER campaign_edit BEFORE UPDATE ON public.campaigns FOR EACH ROW EXECUTE FUNCTION public.validate_campaign_edit();
CREATE TABLE public.donations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id uuid NOT NULL REFERENCES public.campaigns(id), donor_id uuid NOT NULL REFERENCES public.profiles(id), amount numeric NOT NULL CHECK(amount>0 AND amount<=1000000), request_id uuid NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.donations TO authenticated; GRANT ALL ON public.donations TO service_role; ALTER TABLE public.donations ENABLE ROW LEVEL SECURITY;
CREATE POLICY donations_read ON public.donations FOR SELECT TO authenticated USING(donor_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.campaigns c WHERE c.id=campaign_id AND c.organizer_id=auth.uid()));
CREATE INDEX donations_campaign ON public.donations(campaign_id); CREATE INDEX donations_donor ON public.donations(donor_id); CREATE INDEX campaigns_status ON public.campaigns(status);
CREATE FUNCTION public.campaign_totals() RETURNS TABLE(campaign_id uuid, raised numeric, backers bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT c.id,COALESCE(sum(d.amount),0),count(DISTINCT d.donor_id) FROM public.campaigns c LEFT JOIN public.donations d ON d.campaign_id=c.id WHERE c.status='approved' OR c.organizer_id=auth.uid() OR public.has_role(auth.uid(),'admin') GROUP BY c.id $$;
REVOKE ALL ON FUNCTION public.campaign_totals() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.campaign_totals() TO anon,authenticated;
CREATE FUNCTION public.contribute(target uuid, contribution numeric, idempotency_key uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'donor') THEN RAISE EXCEPTION 'Please sign in with a donor account'; END IF; IF contribution IS NULL OR contribution<=0 OR contribution>1000000 THEN RAISE EXCEPTION 'Enter an amount between ₹1 and ₹10,00,000'; END IF; PERFORM 1 FROM public.campaigns WHERE id=target AND status='approved' FOR SHARE; IF NOT FOUND THEN RAISE EXCEPTION 'This campaign is not available for support'; END IF; SELECT id INTO result FROM public.donations WHERE request_id=idempotency_key AND donor_id=auth.uid(); IF result IS NOT NULL THEN RETURN result; END IF; INSERT INTO public.donations(campaign_id,donor_id,amount,request_id) VALUES(target,auth.uid(),contribution,idempotency_key) RETURNING id INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.contribute(uuid,numeric,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.contribute(uuid,numeric,uuid) TO authenticated;
CREATE TABLE public.moderation_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), admin_id uuid NOT NULL REFERENCES public.profiles(id), target_id uuid NOT NULL, target_type text NOT NULL, decision text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.moderation_history TO authenticated; GRANT ALL ON public.moderation_history TO service_role; ALTER TABLE public.moderation_history ENABLE ROW LEVEL SECURITY; CREATE POLICY moderation_read ON public.moderation_history FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.moderate(target uuid, kind text, decision text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator access required'; END IF; IF decision NOT IN ('approved','rejected') OR kind NOT IN ('organizer','campaign') THEN RAISE EXCEPTION 'Invalid review'; END IF; IF kind='organizer' THEN UPDATE public.profiles SET approval_status=decision WHERE id=target AND public.has_role(target,'organizer'); ELSE UPDATE public.campaigns SET status=decision WHERE id=target; END IF; IF NOT FOUND THEN RAISE EXCEPTION 'Submission not found'; END IF; INSERT INTO public.moderation_history(admin_id,target_id,target_type,decision) VALUES(auth.uid(),target,kind,decision); END $$;
REVOKE ALL ON FUNCTION public.moderate(uuid,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.moderate(uuid,text,text) TO authenticated;
INSERT INTO public.campaigns(id,organizer_name,title,description,category,goal_amount,image_url,status,is_sample) SELECT id::uuid,organizer,title,description,category,goal,image,'approved',true FROM (VALUES ('11111111-1111-4111-8111-111111111111','The Learning Collective','A brighter future starts in a classroom','Every child deserves a place to learn, dream, and grow. Help provide books, classroom essentials, and a safe learning environment for children in rural India. This sample campaign demonstrates how your support can create meaningful opportunities.','Education',250000,'classroom'),('22222222-2222-4222-8222-222222222222','Roots for Tomorrow','Plant a forest. Grow a tomorrow.','Support community-led restoration of native forests. This sample campaign brings local volunteers together to plant saplings, restore soil, and protect the landscapes that sustain us.','Environment',150000,'forest'),('33333333-3333-4333-8333-333333333333','Care Without Borders','Bring care closer to home','Help make essential healthcare accessible to rural communities. This sample campaign supports community health camps, basic checkups, and compassionate care for families far from a clinic.','Healthcare',300000,'healthcare')) AS seed(id,organizer,title,description,category,goal,image);